<script setup>

import { reactive, watchEffect } from "vue"

const state = reactive({
 count: 0,
 name: 'Leo'
})

const sleep = ms => new Promise(
  resolve => setTimeout(resolve, ms));

watchEffect(async () => {
 console.log(`Count: ${state.count}`)
 await sleep(1000) 
 console.log(`Name: ${state.name}`)
})

state.count++
state.name = 'Cristiano'

</script>
